#!/bin/bash
python3 - <<'ATPY'

import json, os, sys, time, uuid, shutil

WORK_DIR = os.environ.get("AT_WORK_DIR") or "/tmp"
ASSETS_DIR = os.environ.get("AT_ASSETS_DIR") or os.path.join(WORK_DIR, "assets")
SERIES_DIR = os.path.join(ASSETS_DIR, "series")
AVATAR_DIR = os.path.join(ASSETS_DIR, "avatars")

EPISODE_STATUSES = ("draft", "scripted", "generating", "assembled", "published")
SHOT_STATUSES = ("planned", "still_ready", "generated", "approved", "failed")

def die(msg, **extra):
    out = {"error": msg}
    out.update(extra)
    print(json.dumps(out)); sys.exit(0)

def uid():
    return uuid.uuid4().hex[:10]

def now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())

def slugify(name):
    return "-".join("".join(c if c.isalnum() else " " for c in name.strip().lower()).split())

def arg(name, default=""):
    return os.environ.get("ARG_" + name, "") or default

def arg_json(name):
    raw = os.environ.get("ARG_" + name, "")
    if not raw:
        return None
    try:
        return json.loads(raw)
    except ValueError:
        die("%s must be valid JSON, got: %s" % (name.lower(), raw[:200]))

def arg_int(name, default=None):
    raw = os.environ.get("ARG_" + name, "")
    if not raw:
        return default
    try:
        return int(float(raw))
    except ValueError:
        die(name.lower() + " must be a number, got %r" % raw)

def write_json_atomic(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp-" + uid()
    with open(tmp, "w") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
    os.replace(tmp, path)

def known_characters():
    if not os.path.isdir(AVATAR_DIR):
        return []
    return sorted(os.path.splitext(f)[0] for f in os.listdir(AVATAR_DIR) if f.endswith(".json"))

def validate_cast(cast):
    """Normalize cast entries to [{character, role}] and validate against the avatar library."""
    if cast is None:
        return None
    if not isinstance(cast, list):
        die("cast must be a list of {character, role} objects or character names")
    avail = known_characters()
    out = []
    for entry in cast:
        if isinstance(entry, str):
            entry = {"character": entry, "role": ""}
        if not isinstance(entry, dict) or not entry.get("character"):
            die("each cast entry needs a character name", entry=entry)
        slug = slugify(str(entry["character"]))
        if slug not in avail:
            imgs = [os.path.splitext(f)[0] for f in os.listdir(AVATAR_DIR)] if os.path.isdir(AVATAR_DIR) else []
            if slug not in imgs:
                die("cast character not found in the avatar library: %r (create it with fal_avatar create_avatar save_as=...)" % entry["character"], available=avail)
        out.append({"character": slug, "role": str(entry.get("role") or "")})
    return out

def series_json_path(slug):
    return os.path.join(SERIES_DIR, slug, "series.json")

def load_series(ref):
    if not ref:
        die("series is required (name or slug)")
    slug = slugify(ref)
    p = series_json_path(slug)
    if not os.path.isfile(p):
        avail = []
        if os.path.isdir(SERIES_DIR):
            avail = sorted(d for d in os.listdir(SERIES_DIR)
                           if os.path.isfile(series_json_path(d)))
        die("series not found: %r" % ref, available=avail)
    try:
        return slug, json.load(open(p))
    except ValueError as e:
        die("corrupt series.json for %r: %s" % (ref, e))

def episodes_dir(slug):
    return os.path.join(SERIES_DIR, slug, "episodes")

def episode_dir(slug, num):
    return os.path.join(episodes_dir(slug), "%02d" % num)

def load_episode(slug, ref):
    num = None
    try:
        num = int(str(ref).lstrip("0") or "0")
    except ValueError:
        die("episode must be a number, got %r" % ref)
    p = os.path.join(episode_dir(slug, num), "episode.json")
    if not os.path.isfile(p):
        avail = sorted(os.listdir(episodes_dir(slug))) if os.path.isdir(episodes_dir(slug)) else []
        die("episode %s not found in series %r" % (ref, slug), available=avail)
    try:
        return num, json.load(open(p)), p
    except ValueError as e:
        die("corrupt episode.json for %s/%02d: %s" % (slug, num, e))

def ingest_file(src, ep_dir, rel_target):
    """Copy an artifact into the episode tree and return the relative path.
    Accepts absolute/workspace paths; already-relative paths are returned as-is
    (after checking they exist under the episode dir)."""
    if not src:
        return src
    if not os.path.isabs(src):
        p = os.path.join(ep_dir, src)
        if not os.path.isfile(p):
            die("file not found under episode dir: " + src)
        return src
    sp = os.path.expanduser(src)
    if not os.path.isfile(sp):
        die("file not found: " + sp)
    dest = os.path.join(ep_dir, rel_target)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    if os.path.abspath(sp) != os.path.abspath(dest):
        shutil.copyfile(sp, dest)
    return rel_target

name = arg("NAME")
if not name:
    die("name is required")
slug = slugify(name)
p = series_json_path(slug)
if os.path.isfile(p):
    die("series already exists: %s (use series_update or series_get)" % slug)
cast = validate_cast(arg_json("CAST")) or []
style = {
    "block": arg("STYLE_BLOCK"),
    "negative": arg("NEGATIVE"),
    "seed": arg_int("SEED"),
    "aspect_ratio": arg("ASPECT_RATIO", "16:9"),
    "draft_model": arg("DRAFT_MODEL", "scene_video_budget"),
    "final_model": arg("FINAL_MODEL", "scene_video"),
}
data = {"name": name, "slug": slug, "description": arg("DESCRIPTION"),
        "cast": cast, "style": style, "created_at": now(), "updated_at": now()}
write_json_atomic(p, data)
os.makedirs(episodes_dir(slug), exist_ok=True)
print(json.dumps({"created": data, "dir": os.path.dirname(p)}))

